Translate("ruRU", "swamp-of-sorrows", {
	title = "Болото Печали",
	sections = {
		{
			title = "Обзор",
			text = [=[Болото Печали — затопленный край черной воды, свисающего мха и бесконечного дождя на юго-востоке {link:eastern-kingdoms}Восточных королевств{/link}. Оно лежит к востоку от {link:deadwind-pass}Перевала Мертвого Ветра{/link} и к северу от {link:blasted-lands}Выжженных земель{/link}, а его восточный берег омывает Зловещее море. Деревья его стоят по колено в воде, тропы пропадают в грязи, а в заводях плодятся кроколиски, {link:ogres}огр{/link}омные пауки и ходячие клубки живых водорослей. Ни одно королевство так и не покорило его. {link:orcs}Орки{/link} {link:horde}Орды{/link} держат крепость в его сердце, малый отряд изгнанников цепляется за его западный край, вдоль побережья кишат {link:murlocs}мурлок{/link}и, а зеленые драконы несут безмолвную стражу над озером, где лежит затонувший храм троллей.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не говорит, кто первым дал болоту имя и почему его назвали местом печали. Помнят лишь, что оно издавна было землей изгнанников. Когда тролли Гурубаши низвергли своего кровавого бога {link:hakkar}Хаккара{/link}, они выгнали его жрецов, Атал'ай, из южных джунглей. Атал'ай бежали на север, в эти топи. Там они воздвигли великий храм, {link:temple-of-atal-hakkar}Храм Атал'Хаккара{/link}, где намеревались вернуть своего бога в мир. Зеленые драконы, род которых ведет {red:ysera}Изера{/red}, этого не допустили. Драконы разрушили храм и п{link:ogres}огр{/link}узили его под воды Озера Слез, и там он лежит по сей день. Года ни одна летопись не называет.

К югу от болота лежали Черные топи. Именно там открылся {link:dark-portal}Темный портал{/link}, и оттуда орочья {link:horde}Орда{/link} выступила на войну с королевством {link:azeroth}Азерот{/link} в {link:first-war}Первую войну{/link}. Болото было первым соседом Орды в этом мире.]=],
		},
		{
			title = "Наши дни",
			text = [=[Болото — спорная земля. Вождь {link:thrall}Тралл{/link} держит в его центре крепость {link:stonard}Каменор{/link}, и его {link:orcs}орк{/link}и отправили посланников разузнать, что случилось с затонувшим храмом. У {link:alliance}Альянс{/link}а здесь нет селений. Его караваны лишь проходят мимо по долгой дороге из {link:duskwood}Сумеречного леса{/link} в {link:nethergarde-keep}Крепость Стражей Пустоты{/link}, и многие из них не доходят. На севере народ, который зовут Заблудшими, нападает на всякого, кто забредет к их деревне. На западе, в {link:the-harborage}Убежище{/link}, прячется горстка изгнанников-дренеев, которые делят с ними кровь, но не безумие. Вдоль восточного берега {link:murlocs}мурлок{/link}и с каждым годом смелеют. А над всем этим кружат и ждут зеленые драконы, охраняя храм до того дня, когда его жрецы снова зашевелятся.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}{link:orcs}Орки{/link} {link:stonard}Каменор{/link}а.{/b} Воины, разведчики и торговцы Орды, которые держат единственную крепость болота и стерегут его дороги и побережье.
• {b}Дренеи Убежища.{/b} Малый отряд изгнанников на западе, пришедших в {link:azeroth}Азерот{/link} издалека и теперь страшащихся собственной родни.
• {b}Заблудшие.{/b} Родня дренеев, которую свел с ума долгий путь сюда. Они держат {link:fallow-sanctuary}Болотное пристанище{/link} на севере.
• {b}Зеленые драконы.{/b} Дракончики, змеевики и чешуйчатые ратники рода, который ведет Изера, стерегут {link:pool-of-tears}Озеро Слез{/link} и земли вокруг него. Дракон {link:itharius}Итарий{/link} живет в пещере на юго-западе.
• {b}Мурлоки.{/b} Племена {link:murlocs}мурлоков{/link} Тростникового берега кишат вдоль восточного побережья.
• {b}Звери топей.{/b} Кроколиски-пилозубы, ягуары, пантеры, {link:ogres}огр{/link}омные пауки и ходячие водоросли, которых зовут болотниками и спутанными ужасами.
• {b}Атал'ай.{/b} {link:trolls}Тролли{/link}-жрецы бога {link:hakkar}Хаккар{/link}а все еще обитают в затонувшем храме под Озером Слез.]=],
		},
		{
			title = "История",
			text = [=[• {b}Изгнание Атал'ай.{/b} Изгнанные племенами Гурубаши, жрецы бога {link:hakkar}Хаккар{/link}а воздвигли в болоте свой храм.
• {b}Затопление храма.{/b} Зеленые драконы разбили храм и утопили его, чтобы кровавый бог не смог вернуться через него.
• {b}{link:first-war}Первая война{/link}.{/b} {link:dark-portal}Темный портал{/link} открылся в Черных топях на юге, и {link:horde}Орда{/link} впервые ступила в этот мир у края болота.
• {b}Основание {link:stonard}Каменор{/link}а.{/b} Ни одна летопись не говорит, когда {link:orcs}орк{/link}и построили Каменор. Сегодня это крепость вождя на юге, которую кормит долгая дорога снабжения из Лагеря {link:grom-gol-base-camp}Гром'гол{/link} в {link:stranglethorn-vale}Тернистой долине{/link}.
• {b}Наши дни.{/b} Орда изучает храм, {link:alliance}Альянс{/link} торопит свои караваны мимо, а драконы ждут.]=],
		},
		{
			title = "Предания болота",
			text = [=[• {link:explorers-league}Лига исследователей{/link} {link:ironforge}Стальгорна{/link} давно искала {link:temple-of-atal-hakkar}Храм Атал'Хаккара{/link}. Старый {link:dwarves}дворф{/link} из Лиги летал над болотом на грифоне и так его и не нашел. Нашли его только с земли — затонувшим под Озером Слез.
• Дренеи называют священный кристалл дренетистом. Говорят, что он происходит из места, где летают горы и правят демоны. Шаман {link:centaurs}кентавр{/link}ов из {link:desolace}Пустошей{/link} однажды послал за его осколком на болото.
• Курьер ордена {link:kirin-tor}Кирин-Тора{/link} однажды потерял здесь драгоценный трактат. Его написал {link:khadgar}Кадгар{/link}, и предназначался он для Крепости Стражей Пустоты, а отняли его у курьера ходячие водоросли топей.
• Под старым мостом на западе болота, близ дороги с Перевала Мертвого Ветра, искателям сокровищ оставлены нацарапанные загадки. Загадки говорят о человеке по имени Кортелло и ведут за море и обратно.
• Гоблины хорошо платят за пыль снов — блестящий порошок, который собирают с дракончиков болота.]=],
		},
	},
})

Translate("ruRU", "stonard", {
	title = "Каменор",
	sections = {
		{
			title = "Обзор",
			text = [=[Каменор — крепость {link:horde}Орды{/link} в сердце болота. Его стены из темного камня и тяжелых бревен поднимаются на сухой земле среди заводей, а башни глядят на мили тростника и воды. Это сильнейший оплот вождя на юге {link:eastern-kingdoms}Восточных королевств{/link}. Отсюда конные гонцы везут приказы в {link:blasted-lands}Выжженные земли{/link}, скороходы несут донесения в {link:kargath}Каргат{/link} в {link:badlands}Бесплодных землях{/link}, а ветрокрылы летят на север. В стенах держат свои залы наставники всех ремесел, а торговец отправляет мясо с побережья в {link:orgrimmar}Оргриммар{/link}.]=],
		},
		{
			title = "В стенах",
			text = [=[В Каменоре есть пленник. Под стражей держат лазутчика {link:alliance}Альянс{/link}а, человека, и он уверяет, что знает о предательстве, которое выходит за пределы самого Альянса. Крепость дает приют и посланнику вождя {link:fel-zerul}Фел'зерул{/link}у, присланному узнать судьбу затонувшего храма.]=],
		},
	},
})

Translate("ruRU", "pool-of-tears", {
	title = "Озеро Слез",
	sections = {
		{
			title = "Обзор",
			text = [=[Озеро Слез — широкое тихое озеро на востоке болота. Из его мелководья поднимаются разбитые колонны и остатки старых лестниц. Под его водами лежит {link:temple-of-atal-hakkar}Храм Атал'Хаккара{/link}, который зеленые драконы разрушили и утопили, чтобы жрецы бога {link:hakkar}Хаккара{/link} никогда не смогли завершить свой призыв. В иле его берегов до сих пор находят обломки Атал'ай: идолов, фетиши и резные камни. Озеро стерегут драконы рода, который ведет Изера. Змеевики и чешуйчатые ратники стоят на его берегах и никого не подпускают без причины. Атал'ай все еще обитают в затопленных залах внизу.]=],
		},
	},
})

Translate("ruRU", "fallow-sanctuary", {
	title = "Болотное пристанище",
	sections = {
		{
			title = "Обзор",
			text = [=[Болотное пристанище — деревня Заблудших на севере болота. Ее хижины из тростника и шкур теснятся вокруг кухонных костров, а ее охотники, рыбаки и провидцы уходят из нее в топи. Заблудшие похожи на дренеев Убежища, ведь когда-то они были одним народом. Но долгий путь, приведший их в {link:azeroth}Азерот{/link}, сломил их разум, и теперь они хватают или убивают всякого, кто забредет поближе. Среди их хижин копится краденое добро: священные кристаллы дренетиста, отнятые у Убежища, и повозки каравана {link:alliance}Альянс{/link}а. Деревней правит их вождь. Заблудший {link:ongeku}Онгеку{/link} держит там осколок кристалла дренетиста как свою собственность.]=],
		},
	},
})

Translate("ruRU", "the-harborage", {
	title = "Убежище",
	sections = {
		{
			title = "Обзор",
			text = [=[Убежище — маленький приют на северо-западе болота, где обосновалась горстка изгнанников-дренеев. Их мало, и вооружены они плохо. Их родня, Заблудшие из Болотного пристанища, украла их священные кристаллы, а громила {link:noboru-the-cudgel}Нобору{/link} месяцами охотится на них со своей дубиной. От имени изгнанников говорит {link:magtoor}Магтур{/link}, а среди них трудится кожевник Масат Т'андр. Они принимают путников под любым знаменем, если те приходят с миром, ведь у них нет сил кого-либо прогнать.]=],
		},
	},
})

Translate("ruRU", "itharius-s-cave", {
	title = "Пещера Итара",
	sections = {
		{
			title = "Обзор",
			text = [=[Пещера Итара лежит на дальнем юго-западе болота, скрытая среди мокрых деревьев у границ {link:blasted-lands}Выжженных земель{/link}. Это логово, где живет {link:itharius}Итарий{/link}, дракон зеленого рода. Юные дракончики его породы спят и играют в топи у ее входа, и пыль, что осыпается с их крыльев, мерцает во мраке как иней. Немногие приходят сюда незваными. Те же, кто приходит, обычно ищут помощи, какую может дать только дракон.]=],
		},
	},
})

Translate("ruRU", "misty-reed-strand", {
	title = "Тростниковый берег",
	sections = {
		{
			title = "Обзор",
			text = [=[Тростниковый берег — длинное восточное побережье болота, где топь сменяется песком и серым прибоем Зловещего моря. Его пляжи заполонили {link:murlocs}мурлок{/link}и: налетчики, пожиратели плоти, плеватели чернил и оракулы. Среди скал снуют {link:ogres}огр{/link}омные ползуны, а на мелководье таятся пилозубые щелкуны. На его южном конце стоит Тростниковая застава, небольшой лагерь Орды. Ее {link:orcs}орк{/link}и следят за морем и поднимут тревогу в {link:stonard}Каменор{/link}е, если мурлоки когда-нибудь придут большой силой.]=],
		},
	},
})

Translate("ruRU", "misty-valley", {
	title = "Туманная долина",
	sections = {
		{
			title = "Обзор",
			text = [=[Туманная долина — западные врата болота, где мертвые земли {link:deadwind-pass}Перевала Мертвого Ветра{/link} спускаются в топь. В ее низинах в любой час лежит густой туман. Ходячие водоросли болота здесь сильнее всего: это старые болотники, отяжелевшие от мха, и один {link:ogres}огр{/link}омный, которого {link:orcs}орк{/link}и зовут Владыкой трясины и который бродит по дальним западным заводям. Путники с запада первым делом проходят через долину. Она — предупреждение болота о том, что ждет их впереди.]=],
		},
	},
})

Translate("ruRU", "sorrowmurk", {
	title = "Горемрак",
	sections = {
		{
			title = "Обзор",
			text = [=[Горемрак — дальняя восточная топь между Озером Слез и морем. Это самый мрачный угол мрачного края. Здесь несут стражу старейшие дракониды зеленого рода, и говорят, что капитан драконидов Вирмак командует дозорами вокруг храма. В тростниках крадутся теневые пантеры. Даже {link:orcs}орк{/link}и {link:stonard}Каменор{/link}а редко ходят сюда без нужды.]=],
		},
	},
})

Translate("ruRU", "stagalbog", {
	title = "Вязкая топь",
	aliases = { "Пещера у Вязкой топи" },
	sections = {
		{
			title = "Обзор",
			text = [=[Вязкая топь — россыпь гниющих заводей на юго-востоке болота. По ее водам бродят спутанные ужасы из водорослей и корней, а ее берега обходят дозором чешуйчатые ратники зеленых драконов. Близ побережья в холмах открывается пещера. Это логово {link:murlocs}мурлок{/link}ов, и говорят, что внутри обитает их вожак — тот, кого {link:orcs}орк{/link}и зовут Болотным Говоруном. В этой пещере пропали приказы Орды вместе с мурлоками, которые их захватили.]=],
		},
	},
})

Translate("ruRU", "splinterspear-junction", {
	title = "Развилка Расщепленного Копья",
	sections = {
		{
			title = "Обзор",
			text = [=[Развилка Расщепленного Копья — перекресток дорог на западе болота. Здесь дорога с {link:deadwind-pass}Перевала Мертвого Ветра{/link} встречается с путем, что идет на юг, к {link:blasted-lands}Выжженным землям{/link} и {link:nethergarde-keep}Крепости Стражей Пустоты{/link}. Каждый караван {link:alliance}Альянс{/link}а, идущий в крепость, должен пройти здесь, и не все проходят целыми. Останки одного такого каравана лежат у дороги, где его последний стражник все еще стережет то, что оставили Заблудшие.]=],
		},
	},
})

Translate("ruRU", "the-shifting-mire", {
	title = "Ползучая трясина",
	sections = {
		{
			title = "Обзор",
			text = [=[Ползучая трясина — сердце мокрых земель болота, лабиринт заводей и зыбкой почвы между {link:stonard}Каменор{/link}ом и западными дорогами. Ее тропы меняются с каждым дождем, и ни одна ее карта не остается верной надолго. На ее илистых отмелях греются молодые кроколиски, а пауки-печальники развешивают паутину между затопленными деревьями. {link:orcs}Орки{/link} Каменора посылают в нее разведчиков, и не все они возвращаются.]=],
		},
	},
})

Translate("ruRU", "itharius", {
	title = "Итарий",
	subtitle = "Дракон зеленого рода",
	found = "Пещера Итара, на юго-западе болота",
	hint = [=[Найдите дракона, который живет в пещере на юго-западе болота.]=],
	allegiance = "Зеленые драконы · род, который ведет Изера",
	sections = {
		{
			title = "Обзор",
			text = [=[Итарий — дракон зеленого рода, который ведет {red:ysera}Изера{/red} и который хранит {link:emerald-dream}Изумрудный Сон{/link}. Он устроил логово в пещере на юго-западном краю болота, далеко от Озера Слез, где несет стражу остальная его родня. Дракончики его рода спят в топи у его порога. О себе он говорит мало. Он терпелив и серьезен и меряет смертных тем выбором, который они делают.]=],
		},
		{
			title = "Значение",
			text = [=[Зеленые драконы пришли на болото, чтобы не дать жрецам бога {link:hakkar}Хаккара{/link} вернуть его в мир. Большинство из них не подпускает к себе ни одного смертного. Итарий — единственный из этой стражи, кто говорит со смертными как союзник и кто просит их помощи.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он держит логово на краю болота, отдельно от драконов Озера Слез.
• Он говорит со смертными издалека через Камень Клятвы, связанный клятвенным долгом его рода.
• Он присматривает за юными дракончиками своего рода.
• Он посылает своих смертных союзников за помощью до самых {link:winterspring}Зимних Ключей{/link}.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна запись не говорит, как долго Итарий живет на болоте и почему он держит логово так далеко от затонувшего храма. Его возраст и его положение среди зеленых драконов неизвестны.]=],
		},
	},
	chapters = {
		{
			title = "Камень Клятвы",
			hint = [=[Принесите дракону самоцвет, в котором заключена сущность одного из его родичей.]=],
			text = [=[Дракону зеленого рода Эраникусу было поручено следить, чтобы Атал'ай никогда больше не вызвали своего бога. Это поручение не исполнено, и порча храма овладела им. Часть его разума, все еще принадлежащая ему, была заключена в самоцвет и вынесена из затопленных залов. Через Камень Клятвы Итарий просит этот самоцвет. Он не обещает, что дорога будет короткой. Он говорит лишь, что душа, достойная спасения, стоит жертвы.]=],
		},
		{
			title = "Голос для спящего",
			hint = "Последуйте совету дракона и отправляйтесь на далекий север.",
			text = [=[Эраникус лежит между сном и смертью, пойманный в паутину кошмаров. Его сущность тяжко осквернена, но Итарий верит, что до него еще можно дотянуться. Он посылает своего союзника на север, в снега востока Зимних Ключей, к человеку-медиуму {link:umbranse-the-spiritspeaker}Умбранс{/link}у Говорящему с Духами, который говорит от имени мертвых. Эраникус не мертв, но Итарий надеется, что такой дар все же сможет его достичь.]=],
		},
	},
	mentions = {
		{ text = "«Сущность Эраникуса»" },
		{ text = "«Словами самого Эраникуса»" },
		{
			text = [=[«Пыль снов на болоте», пыль, собранная с дракончиков его рода]=],
		},
	},
	bonds = {
		{ id = "eranikus", name = "Эраникус", note = "дракон его рода, которого он стремится спасти" },
		{ id = "umbranse-the-spiritspeaker", name = "Умбранс Говорящий с Духами", note = "смертный союзник в Зимних Ключах" },
	},
})

Translate("ruRU", "fel-zerul", {
	title = "Фел'зерул",
	subtitle = "Посланник вождя",
	found = "Каменор, в большом зале",
	hint = [=[Поговорите с орком из Каменора, который изучает затонувший храм.]=],
	allegiance = "Орда · Каменор",
	sections = {
		{
			title = "Обзор",
			text = [=[Фел'зерул — {link:orcs}орк{/link}, которого вождь {link:thrall}Тралл{/link} послал в {link:swamp-of-sorrows}Болото Печали{/link} узнать, что за странные дела творятся в Храме {link:temple-of-atal-hakkar}Атал'Хаккар{/link}а. Он шел, ожидая найти храм троллей, полный темных заклинателей. Вместо этого он нашел озеро, под которым затонул храм, и зеленых драконов на страже у берега. С тех пор он трудится в {link:stonard}Каменор{/link}е, складывая эту историю из обрывков, оставшихся от Атал'ай.]=],
		},
		{
			title = "Значение",
			text = [=[Фел'зерул олицетворяет Орду, которая хочет понимать силы своего мира. Он страшится Атал'ай, но верит и в то, что их заклинания однажды могут послужить Орде. Благодаря его терпеливым изысканиям {link:horde}Орда{/link} узнаёт о пророке, который ведет храм, и об обряде, способном вернуть кровавого бога.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он собирает идолов и фетиши Атал'ай вокруг Озера Слез.
• Его разведчики приносят приговор об изгнании, написанный кровью на высушенной коже.
• Он отправляет реликвии храма на север, жрецу-изгнаннику Атал'ай во {link:the-hinterlands}Внутренних землях{/link}.
• Он посылает в сам затонувший храм поборников Орды.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ничего не написано о жизни, которую вел Фел'зерул до того, как вождь послал его на болото.]=],
		},
	},
	chapters = {
		{
			title = "Реликвии озера",
			hint = "Соберите то, что Атал'ай оставили на берегах Озера Слез.",
			text = [=[Никто в {link:stonard}Каменор{/link}е не знал, что Атал'ай делали в своем храме. Фел'зерул знал лишь, что там творилась великая магия и что что-то пошло совсем не так. Он начал с реликвий, лежавших в иле на берегу озера. Одну за другой он изучал их, пытаясь понять, чего надеялись достичь тролли.]=],
		},
		{
			title = "Предостережение изгнанника",
			hint = "Отнесите реликвии храма тому, кого Атал'ай изгнали.",
			text = [=[Разведчик принес ему приговор, написанный кровью на высушенной плоти. В нем назван жрец Атал'ай, осужденный на изгнание к троллям племени Сухокожих во Внутренних землях. Фел'зерул послал реликвии этому изгнаннику. Ответ вернулся тревожный. Реликвии безвредны, сказал изгнанник. Но у верховного жреца {link:jammal-an-the-prophet}Джаммал'ан{/link}а есть пророчество, и если он нашел нужные чары для своих фетишей, весь мир в опасности.]=],
		},
		{
			title = "Фетиши бога Хаккара",
			hint = "Войдите в затонувший храм и захватите фетиши Атал'ай.",
			text = [=[{link:jammal-an-the-prophet}Пророк{/link} Джаммал'ан верит, что, когда {link:hakkar}Хаккар{/link} вернется, бог дарует Атал'ай вечную жизнь. Фел'зерул называет это уловкой, которая приблизит погибель раньше срока. Он боится не столько пророчества, сколько фетишей, которые могут его исполнить. Он послал поборников Орды вниз, в храм, забрать их. Когда они вернулись с фетишами в руках, он назвал их поборниками Орды.]=],
		},
	},
	mentions = {
		{ text = "«{link:pool-of-tears}Озеро Слез{/link}»" },
		{ text = "«{link:atal-ai-exile}Изгнанник Атал'ай{/link}»" },
		{ text = "«Возвращение к Фел'зерулу»" },
		{ text = "«{link:temple-of-atal-hakkar}Храм Атал'Хаккара{/link}»" },
	},
	bonds = {
		{ id = "atal-ai-exile", name = "изгнанник Атал'ай", note = "отверженный жрец, который читает его реликвии" },
		{ id = "thrall", name = "Тралл", note = "вождь, который его послал" },
	},
})

Translate("ruRU", "fallen-hero-of-the-horde", {
	title = "Павший герой Орды",
	subtitle = "Дух болота",
	found = "Южный край болота, у дороги в Выжженные земли",
	hint = "Найдите неупокоенного духа, который ждет у южной дороги.",
	allegiance = "Орда (некогда)",
	aliases = { "Павший герой" },
	sections = {
		{
			title = "Обзор",
			text = [=[У дороги, что ведет на юг, в {link:blasted-lands}Выжженные земли{/link}, стоит призрак воина {link:horde}Орды{/link}. При жизни он командовал полком, который звался Хваткой {link:thrall}Тралл{/link}а. Он повел его в Выжженные земли, не дождавшись приказов, и полк был уничтожен. Теперь он стоит там, где пал, и все еще ждет приказов, которые так и не пришли. Сам он не может нанести удара. Он может только просить помощи у живых и просит ее равно у воинов {link:alliance}Альянс{/link}а и Орды.]=],
		},
		{
			title = "Значение",
			text = [=[Павший герой свидетельствует о войне, которую большая часть мира забыла. За руинами Темного портала Выжженными землями все еще правят демоны под началом владыки {link:razelikh-the-defiler}Разелих{/link}а Осквернителя. Павший герой знает это лучше любого из живых. Он учит, что истинный враг — не {link:alliance}Альянс{/link} и не {link:horde}Орда{/link}, а Легион, который ждет обоих.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он повел полк «Хватка {link:thrall}Тралл{/link}а» в {link:blasted-lands}Выжженные земли{/link} прежде, чем до него дошли приказы.
• Он призывает живых освободить души его воинов и сломить власть владыки демонов.
• Он приветствует {link:alliance}Альянс{/link}, готовый сражаться рядом с Ордой против демонов.
• Он испытывает воинов всех народов и награждает тех, кто оказался достоин.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ничего не написано о жизни этого воина до того, как полк «Хватка {link:thrall}Тралл{/link}а» был послан на юг. Было ли Требор его собственным именем, дух лейтенанта ясно не сказал.]=],
		},
	},
	chapters = {
		{
			title = "Пропавшие приказы",
			hint = [=[Узнайте, что стало с приказами, которых павший командир так и не получил.]=],
			text = [=[В смерти он мог думать только о приказах. {link:dispatch-commander-ruag}Начальник гонцов Руаг{/link} из {link:stonard}Каменор{/link}а клялся, что отправил их. На его всадников на дороге напали из засады {link:murlocs}мурлок{/link}и, и выжил лишь один. Этот уцелевший, {link:bengor}Бенгор{/link}, едва мог говорить. Он сказал, что мурлок по прозвищу {link:swamp-talker}Болотный Говорун{/link} вырвал приказы из его рук и бежал на восток, в пещеру. Павший герой узнал, что его воинам не обязательно было умирать. Девятнадцать из них могли бы уцелеть, если бы только он подождал.]=],
		},
		{
			title = "Камни, что связывают",
			hint = "Освободите души павшего полка из камней Выжженных земель.",
			text = [=[Демоны не дали солдатам полка «Хватка {link:thrall}Тралл{/link}а» покоя. Их души были заключены в камни, разбросанные по Выжженным землям, — всего восемнадцать. Только когда камни будут разбиты, воины обретут мир. Когда раскололся последний, Павший герой понял, что его давний долг начал оплачиваться.]=],
		},
		{
			title = "Пропавший лейтенант",
			hint = [=[Узнайте судьбу единственного лейтенанта, которого так и не нашли.]=],
			text = [=[Один из его офицеров все еще не был найден. Лейтенант {link:kirith-the-damned}Кирит{/link} был заточен и подвергнут пыткам рядом с ним в пещерах демона {link:archmage-allistarj}Аллистарж{/link}а, но под пытками воля лейтенанта сломалась. Павший герой слышал его крики из собственной клетки, а потом не слышал больше ничего. Когда дух лейтенанта наконец нашли, он ответил именем: Требор.]=],
		},
		{
			title = "Осквернитель",
			hint = [=[Соедините расколотый амулет и сразитесь с владыкой демонов Выжженных земель.]=],
			text = [=[{link:razelikh-the-defiler}Разелих Осквернитель{/link} правил Выжженными землями через трех слуг. Каждый носил треть амулета, и, пока они им владели, они не могли умереть в землях демона. Павший герой послал своих поборников сокрушить этих троих и соединить амулет воедино, а затем подняться к логову демона на высочайшей вершине. Когда Осквернитель пал, Павший герой попросил его рог. Он хотел, чтобы тот стал доказательством: в мире, сломанном войной, герои еще живы.]=],
		},
	},
	mentions = {
		{ text = "«Утрата благодати»" },
		{ text = "«Опозоренный»" },
		{
			text = [=[«Мелкие дрязги», {link:alliance}Альянс{/link} приходит ему на помощь]=],
		},
		{ text = "«Повесть о скорби»" },
		{
			text = [=[«Герои былых времен», с духом капрала Тунда {link:great-sundering}Раскол{/link}отого Копыта]=],
		},
		{ text = "«Под покровом тьмы»" },
		{ text = "«Охотник на демонов»" },
		{ text = "«Возвращение в {link:blasted-lands}Выжженные земли{/link}»" },
		{ text = "«Воссоединение расколотого амулета»" },
		{ text = "«Беспокойный дух»" },
		{ text = "«Братство воинов»" },
		{ text = "«Война с Присягнувшими Тени»" },
		{ text = "«Перья вуду»" },
	},
	bonds = {
		{ id = "dispatch-commander-ruag", name = "начальник гонцов Руаг", note = "отправил приказы, которые так и не дошли" },
		{ id = "bengor", name = "Бенгор", note = "последний всадник, который их вез" },
		{ id = "swamp-talker", name = "Болотный Говорун", note = "забрал приказы" },
		{ id = "corporal-thund-splithoof", name = "капрал Тунд Расколотое Копыто", note = "один из его воинов" },
		{ id = "razelikh-the-defiler", name = "Разелих Осквернитель", note = "враг" },
	},
})

Translate("ruRU", "dispatch-commander-ruag", {
	title = "Начальник гонцов Руаг",
	subtitle = "Начальник гонцов Каменора",
	found = "Каменор, в большом зале",
