Translate("ruRU", "helgrum-the-swift", {
	title = "Хелгрум Быстрый",
	subtitle = "Начальник скороходов Каменора",
	found = "Каменор",
	hint = [=[Поговорите с быстрым орком, который ведает скороходами Каменора.]=],
	allegiance = "Орда · Каменор",
	aliases = { "Хелгрум" },
	sections = {
		{
			title = "Обзор",
			text = [=[Хелгрум Быстрый поддерживает связь между {link:stonard}Каменор{/link}ом и другими заставами Орды. Труднейшая ее линия идет на север, в {link:kargath}Каргат{/link} в {link:badlands}Бесплодных землях{/link}, суровом краю рядом с {link:loch-modan}Лок Моданом{/link}, землей {link:alliance}Альянс{/link}а. Скороходы на этой дороге часто пропадают, и ему нужны гонцы, способные проделать этот путь и остаться в живых.]=],
		},
		{
			title = "Значение",
			text = [=[Хелгрум связывает {link:stonard}Каменор{/link} с остальной Ордой на востоке. Из донесений, которые он собирает, он понял, что у {link:alliance}Альянс{/link}а есть свои беды и что некоторые враги могут быть общими.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он посылает скороходов к главе разведчиков {link:kargath}Каргат{/link}а Нике Кровавый Шрам.
• Он читает донесения с севера и взвешивает их для {link:stonard}Каменор{/link}а.]=],
		},
