	sections = {
		{
			title = "Обзор",
			text = [=[Марксен — лазутчик {link:alliance}Альянс{/link}а, человек, пойманный возле лагеря Отрекшихся в Приюте Бродяги и содержащийся пленником в {link:stonard}Каменор{/link}е. Ему уже много дней не дают пить. Он молит о пощаде и уверяет, что владеет тайнами, которые выходят за пределы самого Альянса: предательство в верхах, которое, по его словам, надо вывести на свет. {link:forsaken}Отрекшиеся{/link} хотят получить эти тайны и вежливо просить не намерены.]=],
		},
		{
			title = "Значение",
			text = [=[Тайна этого пленника связывает {link:stonard}Каменор{/link} со скрытыми распрями королевств. Что он знает и кто еще это знает, нигде не записано.]=],
		},
	},
	chapters = {
		{
			title = "Ничего, кроме правды",
			hint = "Принесите пленнику Каменора питье от Отрекшихся.",
			text = [=[Аптекарь Отрекшихся Фаустин сварил сыворотку, развязывающую язык, а ловчий смерти Зраэдус подмешал ее в кружку эля. Кружка эля была единственным, от чего изнывающий от жажды пленник не отказался бы. Марксен с радостью осушил ее и заговорил.]=],
		},
	},
	mentions = {
		{ text = "«Ничего, кроме правды»" },
	},
	bonds = {
		{ id = "deathstalker-zraedus", name = "ловчий смерти Зраэдус", note = "хотел узнать его тайны" },
	},
})

Translate("ruRU", "magtoor", {
	title = "Магтур",
	subtitle = "Голос Убежища",
	found = "Убежище",
	hint = "Поговорите с дренеем, который ведет изгнанников Убежища.",
	allegiance = "Дренеи Убежища",
	sections = {
		{
			title = "Обзор",
			text = [=[Магтур говорит от имени изгнанников-дренеев Убежища. Его народ прошел долгий путь, чтобы достичь {link:azeroth}Азерота{/link}, и не все пережили его невредимыми. Те, кто лишился разума, стали Заблудшими. Они заняли {link:fallow-sanctuary}Болотное пристанище{/link} и украли священные кристаллы дренетиста, принадлежавшие Убежищу. Магтур боится, что без этих кристаллов и его собственный народ может сбиться с пути.]=],
		},
		{
			title = "Значение",
			text = [=[Через него мир узнаёт, кто такие Заблудшие на самом деле: не чудовища, рожденные болотом, а народ, сломленный своим странствием.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он добивается возвращения кристаллов дренетиста, украденных Заблудшими.
• Он радуется смерти громилы {link:noboru-the-cudgel}Нобору{/link}, который наводил ужас на его народ.]=],
		},
	},
	chapters = {
		{
			title = "Украденные кристаллы",
			hint = "Верните кристаллы дренетиста, украденные из Убежища.",
			text = [=[У изгнанников не было сил войти в {link:fallow-sanctuary}Болотное пристанище{/link} и забрать свое. Магтур мог лишь просить чужаков пойти вместо них. Когда кристаллы вернулись, он поблагодарил и сказал, что {link:the-harborage}Убежище{/link} перед ними в долгу.]=],
		},
	},
	mentions = {
		{ text = "«Кристаллы дренетиста»" },
		{ text = "«{link:noboru-the-cudgel}Нобору Дубина{/link}»" },
	},
	bonds = {
		{ id = "noboru-the-cudgel", name = "Нобору Дубина", note = "враг его народа" },
		{ id = "ongeku", name = "Онгеку", note = "Заблудший, владеющий кристаллом дренетиста" },
	},
})

Translate("ruRU", "watcher-biggs", {
