		},
		{
			title = "Значение",
			text = [=[Биггс показывает цену дороги {link:alliance}Альянс{/link}а через болото. Маги Крепости Стражей Пустоты, которые следят за {link:dark-portal}Темным порталом{/link}, зависят от припасов, которым приходится идти этим путем.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он защищает свой разбитый лагерь от зверей болота.
• Он ищет сундук с реагентами, унесенный в {link:fallow-sanctuary}Болотное пристанище{/link}.
• Он чинит свою повозку плавником с побережья.
• Он отправляет самые важные припасы дальше, в {link:nethergarde-keep}Крепость Стражей Пустоты{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Пропавший караван",
			hint = "Верните сундук, который Заблудшие утащили из каравана.",
			text = [=[Прежде чем лишиться чувств, Биггс увидел, как одну из повозок волокут на север, в деревню Заблудших. В ней был сундук с реагентами для магов Крепости Стражей Пустоты. Он не знает, что маги с ними делают. Он знает лишь, что их труд связан с Темным порталом и с безопасностью {link:alliance}Альянс{/link}а.]=],
		},
	},
	mentions = {
		{ text = "«Наступление дикой природы»" },
		{ text = "«Пропавший караван»" },
		{ text = "«Плавник»" },
		{ text = "«Доставка груза»" },
	},
	bonds = {
		{ id = "galen-goodward", name = "Гален Гудвард", note = "еще один пленник Заблудших" },
	},
})

